const r=$input.first().json||{};
const f=r.fields||r;
const name=f['Client']||'';
const slackChannelId=String(f['Slack Channel ID']||'').trim();
const bdrRaw=String(f['BDR Slack Channel ID']||'').trim();
// A BDR channel that is the client channel itself is not a second channel: the main sync already
// covers it, and the thread-id matching runs once. Only a distinct BDR channel gets the BDR leg.
const bdrChannelId=(bdrRaw && bdrRaw!==slackChannelId)?bdrRaw:'';
return [{ json: {
  recordId: r.id||'',
  slackChannelId,
  bdrChannelId,
  bdrSameAsMain: !!(bdrRaw && bdrRaw===slackChannelId),
  driveFolderId: f['driveMainFolderID']||'',
  clientName: name,
  clientSlug: String(name).toLowerCase().replace(/[^a-z0-9]/g, '')
}}];

return $input.all()
  .filter(item => (item.json.messages || []).length > 0)
  .map(item => {
    const messages = item.json.messages;
    const parent = Object.assign({}, messages[0]);
    parent.replies = messages.slice(1);
    return { json: parent };
  });

const names = {};
$input.all().forEach(item => {
  const m = item.json;
  names[m.id] = m.real_name || (m.profile && m.profile.display_name) || m.name || m.id;
});
const messages = $('Attach replies to parent').all().filter(m => m.json && m.json.ts).reverse();
const date = new Date().toISOString().split('T')[0];
const resolve = (t) => String(t || '').replace(/<@([A-Z0-9]+)>/g, (_, id) => '@' + (names[id] || id));
const lines = messages.map(m => {
  const name = names[m.json.user] || m.json.user || 'Unknown';
  const text = resolve(m.json.text);
  let block = '**' + name + '**: ' + text;
  const replies = m.json.replies || [];
  if (replies.length > 0) {
    const replyLines = replies.map(r => {
      const rName = names[r.user] || r.user || 'Unknown';
      const rText = resolve(r.text);
      return '  > **' + rName + '**: ' + rText;
    });
    block += '\n' + replyLines.join('\n');
  }
  return block;
}).join('\n\n');
const content = '# ' + date + ' — Slack\n\n' + (lines || '_No activity._');
return [{ json: { content, filename: date + ' - Slack.md' } }];

let results=[]; let bdr=[]; let rs=0; let launch={}; let scope='all clients';
try{ const sd=$getWorkflowStaticData('global'); results=sd.slackSyncResults||[]; bdr=sd.bdrResults||[]; rs=sd.runStartedAt||0; launch=sd.launch||{}; scope=sd.syncScope||scope; }catch(e){}
const failed=results.filter(r=>!r.ok);
const okOnes=results.filter(r=>r.ok);
const totalMsgs=results.reduce((s,r)=>s+(r.msgs||0),0);
const files=results.filter(r=>r.file).length;
const nf=(x)=>Number(x||0).toLocaleString('en-US');
const lines=okOnes.map(r=> '- **'+r.client+' ('+(r.channel||'?')+'):** '+nf(r.msgs)+' msgs · '+(r.file?'file written':'no file'));
// The BDR leg is part of this run, not a run of its own: its outcome rolls up here.
const bdrFailed=bdr.filter(b=>!b.slackOk||!b.fileId);
const bdrLines=bdr.map(b=>'- **'+b.client+' ('+(b.channel||'?')+'):** '+nf(b.msgs)+' msgs, '+nf(b.threads)+' with threads · '+(b.fileId?'file written':'NOT written')+' · '+(b.matched?(nf(b.comments)+' new thread repl(ies) pushed as prospect comments'):'no prospect matched')+(b.slackOk?'':' (Slack fetch failed: '+(b.slackErr||'unknown')+')'));
const totalBdrMsgs=bdr.reduce((s,b)=>s+(b.msgs||0),0);
const totalComments=bdr.reduce((s,b)=>s+(b.comments||0),0);
const parts=['**'+results.length+' client(s), '+failed.length+' failed'+(bdr.length?' · '+bdr.length+' BDR channel(s), '+bdrFailed.length+' failed':'')+'**','**Scope:** '+scope];
if(lines.length) parts.push('**Clients**\n'+lines.join('\n'));
if(bdrLines.length) parts.push('**BDR channels**\n'+bdrLines.join('\n'));
if(failed.length) parts.push('**FAILED ('+failed.length+')**\n'+failed.map(r=>'- '+r.client+' ('+(r.channel||'?')+'): '+(r.error||'unknown')).join('\n'));
if(bdrFailed.length) parts.push('**BDR FAILED ('+bdrFailed.length+')**\n'+bdrFailed.map(b=>'- '+b.client+': '+(!b.slackOk?('Slack fetch failed: '+(b.slackErr||'unknown')):'log file not written to Drive')).join('\n'));
if(launch.clientFilter && !results.length) parts.push('**Skipped (1, client filter matched no Slack-Sync client)**');
const desc=parts.join('\n\n');
const row={
 'Automation':'Sync Slack Logs to Vault',
 'Status': (failed.length+bdrFailed.length)>0 ? 'Succeeded with errors' : 'Succeeded',
 'Run at': $now.toISO(),
 'Records In': totalMsgs+totalBdrMsgs,
 'Records Out': files+bdr.filter(b=>b.fileId).length+totalComments,
 'Errors': failed.length+bdrFailed.length,
 'Target': results.length+' client channel(s)'+(bdr.length?' + '+bdr.length+' BDR channel(s)':'')+' -> Drive Logs folders',
 'Trigger': launch.trigger||'schedule',
 'Execution ID': String($execution.id),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Duration s': Math.round(($now.toMillis() - (rs||$now.toMillis()))/1000),
 'Description': desc
};
// Client is attached only when the run served exactly one client; never an empty link array.
if(launch.clientFilter) row['Client']=[launch.clientFilter];
return [{json: row}];

const sd=$getWorkflowStaticData('global');
sd.runStartedAt=$now.toMillis();
sd.slackSyncResults=[];
sd.bdrResults=[];
// Scheduled runs sync every enabled client. A launched run with a Client on its launch row syncs that client only.
const cf=String((sd.launch||{}).clientFilter||'');
const all=$input.all().filter(it=>it.json&&it.json.id);
const picked=cf?all.filter(it=>it.json.id===cf):all;
sd.syncScope=cf?(picked.length?'one client (on demand)':'client filter matched no Slack-Sync client'):'all clients';
// Nothing to loop over: emit one placeholder so the Any Clients? gate can route straight to the run log.
if(!picked.length) return [{ json: { _empty:true } }];
return picked;

const sd=$getWorkflowStaticData('global');
if(!Array.isArray(sd.slackSyncResults)) sd.slackSyncResults=[];
let cfg={}; try{cfg=$('Client Config').first().json||{};}catch(e){}
let ok=true, err='';
let msgs=0;
try{ msgs=$('Attach replies to parent').all().map(i=>i.json).filter(m=>m&&m.ts).length; }catch(e){}
try{ const h=$('Get channel messages').first().json||{}; if(h.error){ ok=false; err=String((h.error&&h.error.message)||h.error); } }catch(e){ ok=false; err=err||'channel fetch failed'; }
let fileId='';
try{ const f=$('Create file from text').first().json||{}; if(f.id){ fileId=f.id; } else { ok=false; err=err||String((f.error&&(f.error.message||f.error))||'file not written'); } }catch(e){ ok=false; err=err||'file not written'; }
sd.slackSyncResults.push({client:cfg.clientName||'(unknown)', channel:cfg.slackChannelId||'', msgs:msgs, file:fileId, ok:ok, error:String(err).slice(0,140)});
return [{json:{client:cfg.clientName||'', ok:ok}}];

const threads={};
for(const i of $input.all()){ const m=(i.json&&i.json.messages)||[]; if(m.length>1){ threads[m[0].ts]=m.slice(1); } }
let all=[];
try{ all=($('BDR History').first().json.messages)||[]; }catch(e){ all=[]; }
if(!all.length) return [{json:{channel:'BDR',msg:null}}];
return all.map(m=>{ const p=Object.assign({},m); p.replies=threads[m.ts]||[]; return {json:{channel:'BDR',msg:p}}; });

const date=new Date().toISOString().split('T')[0];
let client='';
try{ client=$('Client Config').first().json.clientName||''; }catch(e){}
let slackOk=false, slackErr='';
try{ const h=$('BDR History').first().json||{}; if(h.ok===true){ slackOk=true; } else { slackErr=String(h.error||h.message||'slack fetch failed (no ok:true)'); } }catch(e){ slackErr='no slack response'; }
try {
  const names={};
  try{ $('Get User Details').all().forEach(i=>{const u=(i&&i.json)||{}; if(u.id) names[u.id]=u.real_name||(u.profile&&u.profile.display_name)||u.name||u.id;}); }catch(e){}
  const resolve=(t)=>String(t||'').replace(/<@([A-Z0-9]+)>/g,(_,id)=>'@'+(names[id]||id));
  const nm=(m)=>{if(!m)return 'Unknown';const p=m.user_profile||{};const bp=m.bot_profile||{};return p.real_name||p.display_name||bp.name||m.username||names[m.user]||m.user||'Unknown';};
  const fmt=(m)=>{let b='**'+nm(m)+'**: '+resolve(m&&m.text);const reps=(m&&m.replies)||[];if(reps.length){b+='\n'+reps.map(r=>'  > **'+nm(r)+'**: '+resolve(r&&r.text)).join('\n');}return b;};
  const bdr=$input.all().map(i=>i.json).filter(x=>x&&x.channel==='BDR').map(x=>x.msg).filter(Boolean).reverse();
  const content='# '+date+' — Slack BDR ('+(client||'client')+')\n\n'+(bdr.length?bdr.map(fmt).join('\n\n'):'_No activity._');
  return [{json:{content, filename: date+' - Slack BDR.md', slackOk, slackErr}}];
} catch(e){
  return [{json:{content:'# '+date+' — Slack BDR ('+(client||'client')+')\n\nFORMAT ERROR: '+String((e&&e.message)||e), filename: date+' - Slack BDR.md', slackOk:false, slackErr:String((e&&e.message)||e)}}];
}

const isBotMsg=(m)=>!!(m&&(m.bot_id||m.app_id||m.subtype));
const items=$input.all().map(i=>i.json).filter(x=>x&&x.msg);
const out=[];
for(const x of items){
  const p=x.msg;
  const botUsers=new Set();
  if(isBotMsg(p)&&p.user) botUsers.add(p.user);
  const human=((p.replies)||[]).filter(r=>r&&!r.bot_id&&!r.app_id&&!r.subtype&&r.user&&!botUsers.has(r.user)&&String(r.text||'').trim());
  if(!human.length) continue;
  out.push({json:{ts:String(p.ts||''), replies:human}});
}
return out.length?out:[{json:{ts:'', replies:[]}}];

const rec=$json||{};
const f=rec.fields||rec;
const ts=String(f['BDR Thread TS']||'');
let card=null;
try{ card=$('BDR Cards With Replies').all().map(i=>i.json).find(c=>c&&ts!==''&&String(c.ts||'')===ts)||null; }catch(e){}
return { json: { record_id: rec.id||'', prospect_name: f.Name||'', ts: ts, replies: (card&&card.replies)||[] } };

const resp=$json||{};
const comments=resp.comments||[];
let rid='';
try{ rid=$('Attach Card').item.json.record_id||''; }
catch(e){ try{ const a=$('Attach Card').all(); if(a.length===1) rid=(a[0].json&&a[0].json.record_id)||''; }catch(e2){} }
return { json: { record_id: rid, seen: comments.map(c=>String((c&&c.text)||'')).join('\n') } };

const seenBy={};
for(const i of $input.all()){ const j=(i&&i.json)||{}; const rid=j.record_id||''; if(!rid) continue; seenBy[rid]=(seenBy[rid]||'')+'\n'+(j.seen||''); }
const names={};
try{ $('Get User Details').all().forEach(i=>{const u=(i&&i.json)||{}; if(u.id) names[u.id]=u.real_name||(u.profile&&u.profile.display_name)||u.name||u.id;}); }catch(e){}
const resolve=(t)=>String(t||'').replace(/<@([A-Z0-9]+)>/g,(_,id)=>'@'+(names[id]||id));
let cards=[];
try{ cards=$('Attach Card').all().map(i=>(i&&i.json)||{}); }catch(e){}
const out=[]; const posted=new Set();
for(const a of cards){
  const rid=a.record_id||''; if(!rid) continue;
  if(!Object.prototype.hasOwnProperty.call(seenBy,rid)) continue;
  const seen=seenBy[rid]||'';
  const nm=a.prospect_name||'';
  for(const r of (a.replies||[])){
    const ts=String((r&&r.ts)||''); if(!ts) continue;
    const marker='⟦bdr:'+ts+'⟧';
    if(seen.indexOf(marker)!==-1) continue;
    const key=rid+marker; if(posted.has(key)) continue;
    const txt=resolve((r&&r.text)||'').trim(); if(!txt) continue;
    posted.add(key);
    const d=new Date((parseFloat(ts)||0)*1000).toISOString().slice(0,10);
    out.push({json:{record_id:rid, text:'BDR call update — '+d+' — '+nm+'\n\n'+txt+'\n\n'+marker}});
  }
}
return out;

const sd=$getWorkflowStaticData('global');
if(!Array.isArray(sd.bdrResults)) sd.bdrResults=[];
let cfg={}; try{ cfg=$('Client Config').first().json||{}; }catch(e){}
let msgs=0, threads=0;
try{ const it=$('BDR Attach').all().map(i=>i.json).filter(x=>x&&x.msg); msgs=it.length; threads=it.filter(x=>((x.msg.replies)||[]).length>0).length; }catch(e){}
let filename='', slackOk=true, slackErr='';
try{ const f=$('Format BDR File').first().json||{}; filename=f.filename||''; slackOk=f.slackOk!==false; slackErr=f.slackErr||''; }catch(e){}
let fileId=''; try{ fileId=($('Create BDR Log File').first().json||{}).id||''; }catch(e){}
let matched=false; try{ matched=$('Attach Card').all().some(i=>i.json&&i.json.record_id); }catch(e){}
let comments=0; try{ comments=$('Diff New Replies').all().filter(i=>i.json&&i.json.record_id).length; }catch(e){}
sd.bdrResults.push({recordId:cfg.recordId||'', client:cfg.clientName||'', channel:cfg.bdrChannelId||'', msgs:msgs, threads:threads, filename:filename, fileId:fileId, matched:matched, comments:comments, slackOk:slackOk, slackErr:String(slackErr).slice(0,140), runAt:$now.toISO()});
return [{json:{bdr:true, client:cfg.clientName||''}}];

// Run Context: one shape for every run, launched or scheduled.
// sd.launch.recordId  = the Hub Automations row this run was launched from ('' on a schedule)
// sd.launch.trigger   = 'form' when launched from the Hub, 'schedule' otherwise
// sd.launch.clientFilter = the launch row's Client link (one record id) to scope the run to one client; '' = all clients
const sd=$getWorkflowStaticData('global');
let launch=null;
try{ const r=$('Fetch Launch Record').first().json; if(r&&r.id) launch=r; }catch(e){}
const f=(launch&&launch.fields)||launch||{};
const cl=Array.isArray(f.Client)&&f.Client.length?f.Client[0]:'';
const clientFilter=(cl&&typeof cl==='object')?String(cl.id||''):String(cl||'');
sd.launch={ recordId: launch?String(launch.id):'', trigger: launch?'form':'schedule', clientFilter, startedAt:$now.toMillis() };
return [{ json: Object.assign({}, sd.launch) }];
